#include "dual_checkpoint_probe.cuh"
#include <random>
#include "dual_model_file.hpp"
#include <cstdio>
int main(){try{using namespace tao::dual;Config c;c.layers=1;c.d=4;c.s=2;c.m=3;c.e=8;c.vocab=261;CpuModel init(c);std::mt19937 rng(981);std::normal_distribution<float>d(0,.1f);for(auto&kv:init.w)for(float&v:kv.second)v=kv.first.find("norm")!=std::string::npos?1.f:d(rng);GpuTrainer a(init),b(init);auto train=[](GpuTrainer&t,unsigned token){auto y=t.graph.step(token);seed_loss(y,(token+1)%261,true);t.graph.tape.backward();t.detach();t.update(1);};train(a,17);save_probe(a,"build/dual_checkpoint_probe.bin");load_probe(b,"build/dual_checkpoint_probe.bin");train(a,18);train(b,18);size_t count=0;for(auto&s:a.spec){if(a.master.at(s.name)->host()!=b.master.at(s.name)->host()||a.moment.at(s.name)->host()!=b.moment.at(s.name)->host()||a.variance.at(s.name)->host()!=b.variance.at(s.name)->host())throw std::runtime_error("resume");count+=s.elements();}auto effective=effective_cpu(a);save_model(effective,"build/dual_model_probe.dsm");auto cpu=load_model("build/dual_model_probe.dsm");if(cpu.w!=effective.w)throw std::runtime_error("packed roundtrip");auto state=cpu.initial();for(unsigned l=0;l<c.layers;++l){state[l].s=a.graph.s[l]->value.host();state[l].m=a.graph.m[l]->value.host();}double worst=0;for(unsigned token:{19u,20u,259u}){auto x=cpu.step(token,state),y=a.graph.step(token)->value.host();for(size_t i=0;i<x.size();++i){double e=std::abs(x[i]-y[i]);if(e>2e-5*(1+std::abs(x[i])))throw std::runtime_error("cpu export");worst=std::max(worst,e);}}printf("PASS resume master/moments params=%zu steps=%u CPU_effective_max=%.9g\n",count,a.steps,worst);return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
